import java.util.Random;
import weka.core.*;
import weka.core.converters.ConverterUtils.DataSource;
import weka.classifiers.trees.J48;

// Input: ARFF generated by traffic_forensics.prepare. Class 0 is miner.
class CompareWeights {
    public static void main(String[] args) throws Exception {
        Instances data = DataSource.read(args[0]);
        data.setClassIndex(data.numAttributes()-1);
        if (!data.classAttribute().value(0).equals("miner")) throw new IllegalArgumentException("Class order");
        Random random = new Random(1);
        data.randomize(random);
        data.stratify(5);
        String[] modes = {"original", "intermediate", "balanced"};
        int[][] counts = new int[3][4];
        for (int fold=0; fold<5; fold++) {
            Instances train = data.trainCV(5, fold, random);
            Instances test = data.testCV(5, fold);
            int positives = train.attributeStats(train.classIndex()).nominalCounts[0];
            int negatives = train.size()-positives;
            for (int mode=0; mode<modes.length; mode++) {
                double ratio = Math.pow((double)negatives/positives, mode/2.0);
                double scale = train.size()/(negatives + positives*ratio);
                for (Instance item : train)
                    item.setWeight(scale*(item.classValue()==0 ? ratio : 1));
                J48 tree = new J48();
                tree.setMinNumObj(100);
                tree.buildClassifier(train);
                for (Instance item : test) {
                    int actual = (int)item.classValue(), predicted = (int)tree.classifyInstance(item);
                    counts[mode][actual*2+predicted]++;
                }
            }
        }
        System.out.println("mode,tp,fn,fp,tn");
        for (int m=0; m<modes.length; m++)
            System.out.printf("%s,%d,%d,%d,%d%n", modes[m], counts[m][0], counts[m][1], counts[m][2], counts[m][3]);
    }
}
